#!/usr/bin/env python3
"""Metadata-only closure walk for vllm==0.30.0 on CPython 3.13 / Linux / glibc 2.41.

Uses only: PyPI simple JSON API (file listings) and PEP 658 .metadata files.
Never downloads wheels or sdists. All responses are cached under ./cache.
"""
import collections
import concurrent.futures as cf
import email.parser
import json
import os
import sys
import time
import urllib.error
import urllib.request

from packaging.requirements import Requirement
from packaging.specifiers import SpecifierSet
from packaging.tags import compatible_tags, cpython_tags
from packaging.utils import canonicalize_name, parse_sdist_filename, parse_wheel_filename
from packaging.version import Version

S = os.path.dirname(os.path.abspath(__file__))
LOCKLIST = os.path.join(os.path.dirname(S), 'vllm-amd64-lock-files.txt')
CACHE = os.path.join(S, 'cache')
os.makedirs(os.path.join(CACHE, 'simple'), exist_ok=True)
os.makedirs(os.path.join(CACHE, 'meta'), exist_ok=True)
UA = 'metadata-audit/0.1 (read-only closure check)'
PYFULL = '3.13.5'  # Debian trixie python3.13


def http_get(url, headers=None, tries=5):
    last = None
    for i in range(tries):
        try:
            req = urllib.request.Request(url, headers={'User-Agent': UA, **(headers or {})})
            with urllib.request.urlopen(req, timeout=90) as r:
                return r.read()
        except urllib.error.HTTPError as e:
            if e.code == 404:
                return None
            last = e
        except Exception as e:  # noqa
            last = e
        time.sleep(2 * (i + 1))
    raise RuntimeError(f'GET {url} failed: {last}')


def simple(name):
    n = canonicalize_name(name)
    p = os.path.join(CACHE, 'simple', n + '.json')
    if os.path.exists(p):
        with open(p) as fh:
            return json.load(fh)
    b = http_get(f'https://pypi.org/simple/{n}/', {'Accept': 'application/vnd.pypi.simple.v1+json'})
    d = json.loads(b) if b is not None else None
    with open(p, 'w') as fh:
        json.dump(d, fh)
    return d


def metadata_text(f):
    fn = f['filename']
    p = os.path.join(CACHE, 'meta', fn + '.metadata')
    if os.path.exists(p):
        with open(p, encoding='utf-8', errors='replace') as fh:
            return fh.read()
    if not f.get('core-metadata'):
        return None
    b = http_get(f['url'] + '.metadata')
    if b is None:
        return None
    with open(p, 'wb') as fh:
        fh.write(b)
    return b.decode('utf-8', errors='replace')


def parse_meta(text):
    msg = email.parser.Parser().parsestr(text, headersonly=True)
    return (msg.get_all('Requires-Dist') or [], msg.get_all('Provides-Extra') or [],
            msg.get('Requires-Python'))


def platforms(machine):
    out = []
    lo = 16 if machine == 'aarch64' else 4
    legacy = {17: 'manylinux2014', 12: 'manylinux2010', 5: 'manylinux1'}
    for m in range(41, lo, -1):
        out.append(f'manylinux_2_{m}_{machine}')
        if m in legacy and (machine == 'x86_64' or m == 17):
            out.append(f'{legacy[m]}_{machine}')
    out.append(f'linux_{machine}')
    return out


def tag_priority(machine):
    plats = platforms(machine)
    tags = list(cpython_tags((3, 13), abis=['cp313'], platforms=plats)) + \
        list(compatible_tags((3, 13), 'cp313', plats))
    return {t: i for i, t in enumerate(tags)}


def marker_env(machine):
    return {
        'implementation_name': 'cpython', 'implementation_version': PYFULL,
        'os_name': 'posix', 'platform_machine': machine, 'platform_release': '',
        'platform_system': 'Linux', 'platform_version': '', 'python_full_version': PYFULL,
        'platform_python_implementation': 'CPython', 'python_version': '3.13',
        'sys_platform': 'linux',
    }


def files_by_version(sj):
    out = collections.defaultdict(list)
    for f in sj['files']:
        fn = f['filename']
        try:
            if fn.endswith('.whl'):
                _, v, _, _ = parse_wheel_filename(fn)
            elif fn.endswith('.tar.gz') or fn.endswith('.zip'):
                _, v = parse_sdist_filename(fn)
            else:
                continue
        except Exception:
            continue
        out[v].append(f)
    return out


def rp_ok(rp):
    if not rp:
        return True
    try:
        return SpecifierSet(rp).contains(PYFULL, prereleases=True)
    except Exception:
        return True


def best_wheel(files, version, prio):
    best = None
    for f in files:
        fn = f['filename']
        if not fn.endswith('.whl') or f.get('yanked'):
            continue
        try:
            _, v, build, tags = parse_wheel_filename(fn)
        except Exception:
            continue
        if v != version:
            continue
        p = min((prio[t] for t in tags if t in prio), default=None)
        if p is None or not rp_ok(f.get('requires-python')):
            continue
        key = (p, -(build[0] if build else 0))
        if best is None or key < best[0]:
            best = (key, f)
    return best[1] if best else None


def load_lock():
    lock = {}
    for line in open(LOCKLIST):
        fn, size, url = line.rstrip('\n').split('\t')
        if not fn.endswith('.whl'):
            continue
        n, v, _, tags = parse_wheel_filename(fn)
        lock[n] = dict(version=v, filename=fn, size=int(size), url=url,
                       tag='-'.join(fn[:-4].split('-')[-3:]))
    return lock


def prefetch(names):
    with cf.ThreadPoolExecutor(6) as ex:
        list(ex.map(simple, names))


def resolve(machine, lock, root='vllm==0.30.0', log=None):
    env = marker_env(machine)
    prio = tag_priority(machine)
    st = {}
    q = collections.deque([(Requirement(root), '<root>')])
    while q:
        req, parent = q.popleft()
        n = canonicalize_name(req.name)
        s = st.get(n)
        if s is None:
            s = st[n] = dict(name=n, extras=set(), specs=[], parents=set(), version=None,
                             wheel=None, sdists=[], reqs=[], enq=set(), excluded=[],
                             notes=[], meta_src=None, rp=None)
            sj = simple(n)
            if sj is None:
                s['notes'].append('NOT ON PYPI')
                s['specs'].append((str(req.specifier), parent))
                s['parents'].add(parent)
                continue
            fbv = files_by_version(sj)
            lv = lock.get(n, {}).get('version')
            if lv is not None and req.specifier.contains(lv, prereleases=True):
                v = lv
                w = best_wheel(fbv.get(v, []), v, prio)
                s['notes'].append('lock version')
            else:
                if lv is not None:
                    s['notes'].append(f'lock version {lv} does not satisfy {req.specifier}')
                vers = sorted(fbv.keys(), reverse=True)
                allowed = [v for v in req.specifier.filter(vers)
                           if not all(f.get('yanked') for f in fbv[v])]
                v, w = (allowed[0] if allowed else None), None
                for cand in allowed:
                    ww = best_wheel(fbv[cand], cand, prio)
                    if ww:
                        v, w = cand, ww
                        break
                s['notes'].append('chosen: newest satisfying version with compatible wheel'
                                  if w else 'chosen: newest satisfying version (NO compatible wheel)')
            s['version'], s['wheel'] = v, w
            s['sdists'] = [f for f in fbv.get(v, []) if not f['filename'].endswith('.whl')]
            s['all_wheels'] = [f['filename'] for f in fbv.get(v, []) if f['filename'].endswith('.whl')]
            if w is not None:
                txt = metadata_text(w)
                if txt is None:
                    s['notes'].append('NO PEP658 METADATA')
                else:
                    reqs, _, rp = parse_meta(txt)
                    s['meta_src'] = w['filename']
                    s['rp'] = rp
                    for r in reqs:
                        try:
                            s['reqs'].append(Requirement(r))
                        except Exception as e:  # noqa
                            s['notes'].append(f'unparseable requirement {r!r}')
            else:
                s['notes'].append('no compatible wheel -> requirements unknown')
        s['specs'].append((str(req.specifier), parent))
        s['parents'].add(parent)
        s['extras'] |= {canonicalize_name(e) for e in req.extras}
        # (re)evaluate requirements with current extras
        s['excluded'] = []
        for r in s['reqs']:
            key = str(r)
            ok = r.marker is None or any(
                r.marker.evaluate({**env, 'extra': e}) for e in [''] + sorted(s['extras']))
            if ok:
                if key not in s['enq']:
                    s['enq'].add(key)
                    q.append((r, n))
            else:
                s['excluded'].append(key)
    # consistency check
    for n, s in st.items():
        s['conflicts'] = []
        if s['version'] is None:
            continue
        for spec, parent in s['specs']:
            if spec and not SpecifierSet(spec).contains(s['version'], prereleases=True):
                s['conflicts'].append(f'{parent} requires {n}{spec}')
    return st


def main():
    lock = load_lock()
    prefetch(sorted(lock))
    out = {}
    for machine in ('x86_64', 'aarch64'):
        st = resolve(machine, lock)
        out[machine] = st
    # dump a json summary for later reporting
    ser = {}
    for machine, st in out.items():
        ser[machine] = {}
        for n, s in st.items():
            w = s['wheel']
            ser[machine][n] = dict(
                version=str(s['version']) if s['version'] else None,
                wheel=w['filename'] if w else None, size=w.get('size') if w else None,
                upload=w.get('upload-time') if w else None, url=w['url'] if w else None,
                sha256=w['hashes'].get('sha256') if w else None,
                sdists=[f['filename'] for f in s['sdists']], all_wheels=s.get('all_wheels', []),
                extras=sorted(s['extras']), parents=sorted(s['parents']), specs=s['specs'],
                reqs=[str(r) for r in s['reqs']], excluded=s['excluded'], notes=s['notes'],
                conflicts=s['conflicts'], meta_src=s['meta_src'], requires_python=s['rp'])
    with open(os.path.join(S, 'closure.json'), 'w') as fh:
        json.dump(ser, fh, indent=1, sort_keys=True)
    print('wrote closure.json')


if __name__ == '__main__':
    main()

